package cn.jingyu.deepseek;

import android.content.Context;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.text.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;import java.util.zip.*;

/** Native, local document writer. Never runs generated programs, macros or spreadsheet formulas. */
public final class ArtifactFiles {
 public static final String[] FORMATS={"docx","pdf","xlsx","md","txt","csv"};
 public static final String[] LABELS={"Word 文档","PDF 文档","Excel 数据表","Markdown","纯文本","CSV 数据表"};
 public static JSONObject create(Context context,JSONObject original)throws Exception {JSONObject spec=new JSONObject(original.toString());spec.put("format",spec.optString("format").toLowerCase(Locale.ROOT));ArtifactSkills.validate(spec);String type=spec.optString("format").toLowerCase(Locale.ROOT);if(!Arrays.asList(FORMATS).contains(type))throw new IOException("暂不支持这个文件格式");String content=spec.optString("content");if(content.length()>1000000)throw new IOException("文件正文过长");if(content.trim().isEmpty()&&spec.optJSONArray("rows")==null&&spec.optJSONArray("sheets")==null)throw new IOException("模型没有提供文件正文，请重新生成或导出现有回答");String base=spec.optString("name","鲸语文档").replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_").trim();base=base.replaceAll("(?i)\\.(docx|pdf|xlsx|pptx|md|txt|csv|html)$","");if(base.isEmpty())base="鲸语文档";if(base.length()>80)base=base.substring(0,80);String name=base+"."+type;String id=UUID.randomUUID().toString()+"."+type;File dir=directory(context);if(!dir.exists()&&!dir.mkdirs())throw new IOException("无法创建文件目录");File file=new File(dir,id),tmp=new File(dir,id+".tmp");try(OutputStream out=new BufferedOutputStream(new FileOutputStream(tmp))){switch(type){case "docx":DocxWriter.write(out,spec);break;case "xlsx":xlsx(out,spec);break;case "pdf":PdfWriter.write(context,out,spec);break;case "csv":out.write(("\ufeff"+csv(rows(spec))).getBytes(StandardCharsets.UTF_8));break;case "txt":out.write(plain(withSources(spec)).getBytes(StandardCharsets.UTF_8));break;default:out.write(withSources(spec).getBytes(StandardCharsets.UTF_8));}}catch(Exception e){tmp.delete();throw e;}if(!tmp.renameTo(file)){tmp.delete();throw new IOException("文件保存失败");}return new JSONObject().put("id",id).put("name",name).put("format",type).put("mime",mime(type)).put("size",file.length()).put("spec",spec);}
 public static File directory(Context c){return new File(c.getFilesDir(),"generated");}
 public static File resolve(Context c,String id)throws IOException {if(!id.matches("[a-f0-9-]{36}\\.(docx|pdf|xlsx|pptx|md|txt|csv|html)"))throw new IOException("文件标识无效");File file=new File(directory(c),id);if(!file.isFile())throw new FileNotFoundException("文件不在本机，可从已保存的内容重新生成");return file;}
 public static String mime(String type){switch(type){case "docx":return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";case "xlsx":return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";case "pptx":return "application/vnd.openxmlformats-officedocument.presentationml.presentation";case "pdf":return "application/pdf";case "html":return "text/html";case "csv":return "text/csv";case "md":return "text/markdown";default:return "text/plain";}}
 public static String preview(JSONObject spec){JSONArray sheets=spec.optJSONArray("sheets");if(sheets!=null){StringBuilder b=new StringBuilder();for(int i=0;i<sheets.length();i++){JSONObject sheet=sheets.optJSONObject(i);if(sheet!=null){b.append("## ").append(sheet.optString("name","工作表")).append("\n\n").append(csv(rows(sheet))).append("\n");if(sheet.optJSONObject("chart")!=null)b.append("图表已嵌入Excel，打开文件可查看和编辑。\n\n");}}return b.toString();}if(!spec.optString("content").isEmpty())return withSources(spec);JSONArray slides=spec.optJSONArray("slides");if(slides!=null){StringBuilder b=new StringBuilder();for(int i=0;i<slides.length();i++){JSONObject s=slides.optJSONObject(i);if(s!=null)b.append("## ").append(s.optString("title")).append("\n\n").append(s.optString("body")).append("\n\n");}return b.toString();}return csv(rows(spec));}
 static String withSources(JSONObject spec){String text=spec.optString("content");JSONArray sources=spec.optJSONArray("sources");if(sources!=null&&sources.length()>0){text+="\n\n## 检索来源\n";for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);if(s!=null)text+="\n"+(i+1)+". "+s.optString("title")+"\n"+s.optString("url")+"\n";}}return text;}
 static String plain(String text){return text.replaceAll("(?m)^#{1,6}\\s+","").replace("**","").replace("```","");}
 static String xml(String s){StringBuilder b=new StringBuilder();for(int offset=0;offset<s.length();){int c=s.codePointAt(offset);offset+=Character.charCount(c);if(c==9||c==10||c==13||c>=32&&c<=0xd7ff||c>=0xe000&&c<=0xfffd||c>=0x10000&&c<=0x10ffff)b.appendCodePoint(c);}return b.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static void entry(ZipOutputStream zip,String name,String value)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(value.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
 static final String HEADER="<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>";
 static String rels(String body){return HEADER+"<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"+body+"</Relationships>";}
 static String rel(String id,String type,String target){return "<Relationship Id=\""+id+"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/"+type+"\" Target=\""+target+"\"/>";}
 static String override(String name,String type){return "<Override PartName=\"/"+name+"\" ContentType=\"application/vnd.openxmlformats-officedocument."+type+"+xml\"/>";}
 static String types(String body){return HEADER+"<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>"+body+"</Types>";}
 static String[] tableCells(String line){return DocumentLayout.cells(line);}
 static String[] tableCellsLegacy(String line){String value=line.trim();if(value.startsWith("|"))value=value.substring(1);if(value.endsWith("|"))value=value.substring(0,value.length()-1);String[] cells=value.split("\\|",-1);for(int i=0;i<cells.length;i++)cells[i]=cells[i].trim();return cells;}
 static JSONArray rows(JSONObject spec){JSONArray rows=spec.optJSONArray("rows");if(rows!=null)return rows;rows=new JSONArray();String text=spec.optString("content");for(String line:text.split("\n")){if(line.trim().startsWith("|")&&line.trim().endsWith("|")){if(line.matches("[| :\\-]+"))continue;JSONArray row=new JSONArray();String[] cells=line.trim().substring(1,line.trim().length()-1).split("\\|",-1);for(String cell:cells)row.put(cell.trim());rows.put(row);}}if(rows.length()>0)return rows;if(!text.contains(",")&&!text.contains("\t"))return new JSONArray();try{return parseCSV(text);}catch(Exception e){return new JSONArray();}}
 static JSONArray parseCSV(String text)throws IOException {JSONArray result=new JSONArray(),row=new JSONArray();StringBuilder cell=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='\"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='\"'){cell.append('"');i++;}else if(quoted||cell.length()==0)quoted=!quoted;else cell.append(c);}else if(!quoted&&(c==','||c=='\t')){row.put(cell.toString());cell.setLength(0);}else if(!quoted&&(c=='\n'||c=='\r')){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;row.put(cell.toString());cell.setLength(0);result.put(row);row=new JSONArray();}else cell.append(c);}if(quoted)throw new IOException("CSV 引号未闭合");if(cell.length()>0||row.length()>0){row.put(cell.toString());result.put(row);}return result;}
 static String csv(JSONArray rows){StringBuilder b=new StringBuilder();for(int i=0;i<rows.length();i++){JSONArray row=rows.optJSONArray(i);if(row==null)continue;for(int j=0;j<row.length();j++){if(j>0)b.append(',');String cell=row.optString(j,"");if(cell.matches("(?s)^\\s*[=+@].*")||cell.matches("(?s)^\\s*-.*")&&!cell.matches("-?[0-9]+(?:\\.[0-9]+)?"))cell="'"+cell;b.append('"').append(cell.replace("\"","\"\"")).append('"');}b.append("\r\n");}return b.toString();}
 static int rowHeight(JSONArray row,boolean header){int lines=1;for(int c=0;c<row.length();c++){String value=row.optString(c);int units=0;for(int k=0;k<value.length();k++)units+=value.charAt(k)>255?2:1;lines=Math.max(lines,Math.max(value.split("\\n",-1).length,(units+32)/33));}return Math.min(409,Math.max(header?30:24,lines*16+10));}
 static String columnWidths(JSONArray rows){StringBuilder b=new StringBuilder();int cols=rows.optJSONArray(0)==null?0:rows.optJSONArray(0).length();for(int c=0;c<cols;c++){int width=12;for(int r=0;r<Math.min(rows.length(),300);r++){String value=rows.optJSONArray(r)==null?"":rows.optJSONArray(r).optString(c);int count=0;for(int k=0;k<value.length();k++)count+=value.charAt(k)>255?2:1;width=Math.max(width,Math.min(44,count+3));}b.append("<col min=\"").append(c+1).append("\" max=\"").append(c+1).append("\" width=\"").append(width).append("\" customWidth=\"1\"/>");}return b.toString();}
 static String column(int n){String s="";do{s=(char)('A'+n%26)+s;n=n/26-1;}while(n>=0);return s;}
 static void xlsx(OutputStream out,JSONObject spec)throws Exception {SpreadsheetWriter.write(out,spec);}
 static void xlsxLegacy(OutputStream out,JSONObject spec)throws Exception {JSONArray data=rows(spec);if(data.length()>10000)throw new IOException("表格最多 10000 行");try(ZipOutputStream z=new ZipOutputStream(out)){String types=override("xl/workbook.xml","spreadsheetml.sheet.main")+override("xl/worksheets/sheet1.xml","spreadsheetml.worksheet")+override("xl/styles.xml","spreadsheetml.styles");entry(z,"[Content_Types].xml",types(types));entry(z,"_rels/.rels",rels(rel("rId1","officeDocument","xl/workbook.xml")));entry(z,"xl/workbook.xml",HEADER+"<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"数据\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");entry(z,"xl/_rels/workbook.xml.rels",rels(rel("rId1","worksheet","worksheets/sheet1.xml")+rel("rId2","styles","styles.xml")));entry(z,"xl/styles.xml",HEADER+"<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><color rgb=\"FFFFFFFF\"/><name val=\"Calibri\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF236F5B\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"2\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"top\"/></xf><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"center\"/></xf></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");StringBuilder sheet=new StringBuilder(HEADER+"<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>"+columnWidths(data)+"</cols><sheetData>");for(int i=0;i<data.length();i++){JSONArray row=data.optJSONArray(i);if(row==null)continue;if(row.length()>256)throw new IOException("表格最多 256 列");sheet.append("<row r=\"").append(i+1).append("\" ht=\"").append(rowHeight(row,i==0)).append("\" customHeight=\"1\">");for(int j=0;j<row.length();j++){Object value=row.opt(j);String ref=column(j)+(i+1);sheet.append("<c r=\"").append(ref).append("\" s=\"").append(i==0?1:0).append("\"");if(value instanceof Number)sheet.append("><v>").append(value).append("</v></c>");else sheet.append(" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(row.optString(j,""))).append("</t></is></c>");}sheet.append("</row>");}sheet.append("</sheetData><autoFilter ref=\"A1:").append(column(Math.max(0,data.getJSONArray(0).length()-1))).append(data.length()).append("\"/><pageMargins left=\"0.5\" right=\"0.5\" top=\"0.6\" bottom=\"0.6\" header=\"0.3\" footer=\"0.3\"/></worksheet>");entry(z,"xl/worksheets/sheet1.xml",sheet.toString());}}
}
